const blacklist = [
  'linkedin.com', 'facebook.com', 'youtube.com', 'instagram.com', 'twitter.com', 'tiktok.com', 'x.com', 'pinterest.com',
  'alibaba.com', 'amazon.com', 'made-in-china.com', 'globalsources.com', 'thomasnet.com', 
  'yellowpages.com', 'yelp.com', 'trustpilot.com', 'crunchbase.com', 'bloomberg.com', 
  'wikipedia.org', 'reddit.com', 'quora.com', 'medium.com', 'tradeimex.in', 'seair.co.in',
  'worldbank.org', 'zippia.com', 'unicargo.com', 'ebay.com', 'walmart.com'
];

const forbiddenTLDs = ['.gov', '.edu'];
const output = [];

// Loop through all incoming Serper keyword outputs
for (const item of $input.all()) {
  const searchResults = item.json.organic || [];
  const currentKeyword = item.json.searchParameters?.q || $("Webhook").item.json.body.original_keyword;

  const cleanResults = searchResults.filter(result => {
    if (!result.link) return false;
    const url = result.link.toLowerCase();

    const isBlacklisted = blacklist.some(domain => url.includes(domain));
    const isForbiddenTLD = forbiddenTLDs.some(tld => url.includes(tld));

    return !isBlacklisted && !isForbiddenTLD;
  });

  cleanResults.forEach(result => {
  let hostname = result.link || '';
  try {
    // Clean string and strip www.
    const parsed = new URL(hostname);
    hostname = parsed.hostname.replace(/^www\./, '');
  } catch (e) {
    // Regex fallback if URL constructor fails
    hostname = hostname.replace(/^(?:https?:\/\/)?(?:www\.)?([^\/]+).*/i, '$1');
  }

  output.push({
    json: {
      original_keyword: currentKeyword,
      url: result.link,
      title: result.title,
      snippet: result.snippet,
      domain: hostname
    }
  });
});
}

return output;

